// M2-3a: the agent KeyStore of the self-host Worker (04 §2.2 "Self-host Worker", §3.1.1; 03 §3; 08
// §3.2). Same contract as the Node keychain KeyStore (packages/node, M1-8a), with the seed from one of
// the two places D-131 names, both in the user's own Cloudflare account:
//   - the Worker secret AGENT_SEED (desktop deploy path, generated on the user's computer), or
//   - the agent item `seed` in the Durable Object, sealed under the Worker secret SEED_WRAP_KEY
//     (Deploy-button path; generated by the Worker on the first `/setup`, M2-3f-1).
// The seed is read for each operation, checked against the agent ID (04 §2.9), used and wiped (04
// §8.3, best effort): the KeyStore keeps no seed bytes between calls. It never returns, logs or sends
// the seed or a key; errors are fixed sentences (I-7). Owner keys are never here (04 §2.5).
//
// Residual (documented in the PR): the Workers runtime hands secrets to the code as JavaScript
// strings, which cannot be wiped; AGENT_SEED and SEED_WRAP_KEY stay in the isolate's `env` for its
// lifetime, as on every Worker. The bytes decoded from them are wiped after each use.
import {
  CryptoInputError,
  KEY_LABELS,
  KeyStoreError,
  MASTER_SEED_LENGTH,
  MAX_KEY_EPOCH,
  cardPopSnapshot,
  decodeBase64url,
  decodeHex,
  decodeHex0x,
  directTransactionSnapshot,
  dropRequestEpoch,
  dropRequestSnapshot,
  encodeHex,
  encodeUtf8,
  equalBytes,
  hkdfSha256,
  nostrEventId,
  parseAgentCard,
  randomBytes,
  wipe,
  type AgentCard,
  type DirectTransaction,
  type DropAuthRequest,
  type EpochOptions,
  type KeyLabel,
  type KeyStore,
  type NostrEvent,
  type PublicIdentity,
  type TypedData,
  type UnsignedNostrEvent,
  type WrappedCek,
} from '@4thtech-io/crypto';
import {
  bip340PublicKey,
  bip340Sign,
  createStoreColumnCipher,
  deriveAgentId,
  derivePublicIdentity,
  deriveSecretKey,
  nip44ConversationKey,
  nip44DecryptWithKey,
  nip44EncryptWithKey,
  signCardPop,
  signDirectTransaction,
  signDropRequest,
  signEnvelopeHash,
  signTypedData,
  unwrapCek,
} from '@4thtech-io/crypto/keystore';
import { rowKeyOf, type SealContext } from '@4thtech-io/core';
import type { DurableObjectStore } from './do-store.js';
import { CloudAgentError } from './errors.js';

/** The two Worker secrets that carry key material. Both optional: which one is set is the path. */
export interface SeedSecrets {
  readonly AGENT_SEED?: string | undefined;
  readonly SEED_WRAP_KEY?: string | undefined;
}

/** A fresh copy of the 32-byte agent seed for one operation. The caller wipes it. */
export type SeedSource = () => Promise<Uint8Array>;

const SEED_HEX = /^[0-9a-f]{64}$/;
const WRAP_KEY_B64URL = /^[A-Za-z0-9_-]{43}$/;

/**
 * The store key of the `enc` columns (07 §3.1) on the cloud: HKDF-SHA256 of the agent seed, salt
 * `agentlink-v1`, info `agentlink/v1/cloud-store-key`, 32 bytes (proposed, owner confirms at merge;
 * M2-3a). Derived, not stored, because the AGENT_SEED path has no other secret to seal a random one
 * under. Its info string differs from every 04 §2.1 purpose label (those end in a u32 epoch), so it is
 * a separate key from all of them, and it does not change with the key epoch.
 */
export const CLOUD_STORE_KEY_INFO = 'agentlink/v1/cloud-store-key';
const STORE_KEY_SALT = 'agentlink-v1';

/** Where the sealed seed lives: the agent item `seed` (cloud-schema.ts), as an `enc` value. */
export const SEALED_SEED_CONTEXT: SealContext = Object.freeze({
  table: 'agent_items' as SealContext['table'],
  column: 'value',
  rowKey: rowKeyOf(['seed']),
});

function seedFromHex(secret: string): Uint8Array {
  if (!SEED_HEX.test(secret)) throw new CloudAgentError('seed_secret_invalid');
  return decodeHex(secret, { length: MASTER_SEED_LENGTH });
}

function wrapKeyOf(secret: string | undefined): Uint8Array {
  if (secret === undefined || secret === '') throw new CloudAgentError('seed_wrap_key_missing');
  if (!WRAP_KEY_B64URL.test(secret)) throw new CloudAgentError('seed_secret_invalid');
  try {
    const key = decodeBase64url(secret);
    if (key.length !== 32) throw new Error('length');
    return key;
  } catch {
    throw new CloudAgentError('seed_secret_invalid');
  }
}

/** Opens the sealed seed text under SEED_WRAP_KEY; wipes the decoded wrap key. */
async function openSealedSeed(
  sealed: string,
  wrapKeySecret: string | undefined,
): Promise<Uint8Array> {
  const key = wrapKeyOf(wrapKeySecret);
  let hex: string;
  try {
    const cipher = await createStoreColumnCipher(key);
    try {
      hex = await cipher.open(SEALED_SEED_CONTEXT, sealed);
    } finally {
      cipher.close();
    }
  } catch {
    throw new CloudAgentError('seed_unreadable');
  } finally {
    wipe(key);
  }
  if (!SEED_HEX.test(hex)) throw new CloudAgentError('seed_unreadable');
  return decodeHex(hex, { length: MASTER_SEED_LENGTH });
}

/**
 * The seed source of this deployment (08 §3.2): AGENT_SEED when set, otherwise the sealed agent item.
 * Both at once is refused (`seed_conflict`): which one is the agent is the owner's decision, never
 * this code's. Neither is `seed_missing` (not set up). Fail closed: nothing here generates a seed.
 */
export function resolveSeedSource(secrets: SeedSecrets, store: DurableObjectStore): SeedSource {
  const sealed = store.readItem('seed');
  const plain = secrets.AGENT_SEED;
  if (plain !== undefined && plain !== '') {
    if (sealed !== null) throw new CloudAgentError('seed_conflict');
    // Checked once now, so a malformed secret fails at open, not at the first signature.
    wipe(seedFromHex(plain));
    return () => Promise.resolve(seedFromHex(plain));
  }
  if (sealed === null) throw new CloudAgentError('seed_missing');
  const wrapKeySecret = secrets.SEED_WRAP_KEY;
  return async () => {
    // Read again each time: the item is write-once (a trigger), so this is the same value.
    const current = store.readItem('seed');
    if (current === null) throw new CloudAgentError('seed_missing');
    return openSealedSeed(current, wrapKeySecret);
  };
}

/**
 * Deploy-button path (08 §3.2): generates the agent seed in the Worker and stores it sealed under
 * SEED_WRAP_KEY, once. Idempotent: an existing sealed seed is kept (`exists`), never replaced (a
 * trigger refuses that too). Refused while AGENT_SEED is set (`seed_conflict`). `/setup` (M2-3f-1)
 * calls it after the setup code; nothing else does. Returns nothing about the seed.
 */
export async function provisionSealedSeed(
  secrets: SeedSecrets,
  store: DurableObjectStore,
): Promise<'created' | 'exists'> {
  if (secrets.AGENT_SEED !== undefined && secrets.AGENT_SEED !== '') {
    throw new CloudAgentError('seed_conflict');
  }
  if (store.readItem('seed') !== null) return 'exists';
  const key = wrapKeyOf(secrets.SEED_WRAP_KEY);
  const seed = randomBytes(MASTER_SEED_LENGTH);
  let sealed: string;
  try {
    const cipher = await createStoreColumnCipher(key);
    try {
      sealed = await cipher.seal(SEALED_SEED_CONTEXT, encodeHex(seed));
    } finally {
      cipher.close();
    }
  } finally {
    wipe(key);
    wipe(seed);
  }
  let outcome: 'created' | 'exists' = 'exists';
  store.updateItem('seed', (current) => {
    if (current !== null) return undefined;
    outcome = 'created';
    return sealed;
  });
  return outcome;
}

function assertEpoch(epoch: unknown): asserts epoch is number {
  if (typeof epoch !== 'number' || !Number.isInteger(epoch) || epoch < 0 || epoch > MAX_KEY_EPOCH) {
    throw new CryptoInputError(
      'invalid_argument',
      'keystore: the epoch must be an integer from 0 to 2^32 - 1',
    );
  }
}

function bytesCopy(value: unknown, what: string): Uint8Array {
  if (!(value instanceof Uint8Array)) {
    throw new CryptoInputError('invalid_argument', `${what} must be a Uint8Array`);
  }
  return new Uint8Array(value);
}

function eventSnapshot(event: unknown): UnsignedNostrEvent {
  if (typeof event !== 'object' || event === null) {
    throw new CryptoInputError('invalid_argument', 'nostr event: must be an object');
  }
  const { kind, created_at: createdAt, tags, content } = event as Record<string, unknown>;
  const copied: unknown = Array.isArray(tags)
    ? Object.freeze(
        tags.map((tag: unknown) => (Array.isArray(tag) ? Object.freeze([...tag]) : tag)),
      )
    : tags;
  return Object.freeze({
    kind,
    created_at: createdAt,
    tags: copied,
    content,
  }) as UnsignedNostrEvent;
}

async function withSecret<T>(
  seed: Uint8Array,
  label: KeyLabel,
  epoch: number,
  fn: (secretKey: Uint8Array) => T | Promise<T>,
): Promise<T> {
  const secretKey = deriveSecretKey(seed, label, epoch);
  try {
    return await fn(secretKey);
  } finally {
    wipe(secretKey);
  }
}

function derivesAgent(seed: Uint8Array, agentId: string): boolean {
  if (seed.length !== MASTER_SEED_LENGTH) return false;
  return equalBytes(
    decodeHex0x(deriveAgentId(seed), { length: 20 }),
    decodeHex0x(agentId, { length: 20 }),
  );
}

function notOwnCard(): CryptoInputError {
  return new CryptoInputError(
    'invalid_argument',
    'signCardPop: the card must be this agent card at the current key epoch',
  );
}

export interface WorkerKeyStoreOptions {
  /** The current key epoch (04 §2.6), as recorded in the store's `identity` row. Default 0. */
  readonly keyEpoch?: number;
  /** The agent ID recorded in the store, if any: a seed that derives another agent is refused. */
  readonly agentId?: string | undefined;
}

export class WorkerKeyStore implements KeyStore {
  readonly #source: SeedSource;
  readonly #agentId: string;
  readonly #keyEpoch: number;
  #closed = false;

  private constructor(source: SeedSource, agentId: string, keyEpoch: number) {
    this.#source = source;
    this.#agentId = agentId;
    this.#keyEpoch = keyEpoch;
  }

  /**
   * Opens the agent of `source`: reads the seed once to derive its agent ID and, when the store
   * records one, checks it (04 §2.9), then wipes it. A foreign seed is an error, never a new identity.
   */
  static async open(
    source: SeedSource,
    options: WorkerKeyStoreOptions = {},
  ): Promise<WorkerKeyStore> {
    const keyEpoch = options.keyEpoch ?? 0;
    assertEpoch(keyEpoch);
    const seed = await source();
    let agentId: string;
    try {
      if (seed.length !== MASTER_SEED_LENGTH) throw new CloudAgentError('seed_unreadable');
      agentId = deriveAgentId(seed);
      if (options.agentId !== undefined && !derivesAgent(seed, options.agentId)) {
        throw new CloudAgentError('identity_mismatch');
      }
    } finally {
      wipe(seed);
    }
    return new WorkerKeyStore(source, agentId, keyEpoch);
  }

  /** The agent ID this KeyStore signs for (public). */
  get agentId(): string {
    return this.#agentId;
  }

  async #withSeed<T>(fn: (seed: Uint8Array) => T | Promise<T>): Promise<T> {
    if (this.#closed) throw new KeyStoreError('keystore_closed', 'keystore: the store is closed');
    const seed = await this.#source();
    try {
      if (this.#closed) throw new KeyStoreError('keystore_closed', 'keystore: the store is closed');
      if (!derivesAgent(seed, this.#agentId)) throw new CloudAgentError('identity_mismatch');
      return await fn(seed);
    } finally {
      wipe(seed);
    }
  }

  #epochOf(options: EpochOptions | undefined): number {
    const epoch = options?.epoch ?? this.#keyEpoch;
    assertEpoch(epoch);
    if (epoch > this.#keyEpoch) {
      throw new KeyStoreError('epoch_unavailable', 'keystore: that key epoch is not available');
    }
    return epoch;
  }

  async getPublicBundle(options?: EpochOptions): Promise<PublicIdentity> {
    const epoch = this.#epochOf(options);
    return this.#withSeed((seed) => derivePublicIdentity(seed, epoch));
  }

  async signNostr(event: UnsignedNostrEvent): Promise<NostrEvent> {
    const fields = eventSnapshot(event);
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.nostr, this.#keyEpoch, (secretKey) => {
        const pubkey = encodeHex(bip340PublicKey(secretKey));
        const id = nostrEventId(pubkey, fields);
        const sig = encodeHex(bip340Sign(secretKey, decodeHex(id)));
        return Object.freeze({ ...fields, id, pubkey, sig });
      }),
    );
  }

  async signEnvelopeHash(envelopeHash: Uint8Array): Promise<string> {
    const hash = bytesCopy(envelopeHash, 'signEnvelopeHash: envelopeHash');
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.nostr, this.#keyEpoch, (secretKey) =>
        encodeHex(signEnvelopeHash(secretKey, hash)),
      ),
    );
  }

  async nip44Encrypt(peer: string, plaintext: string): Promise<string> {
    const peerKey = decodeHex(peer, { length: 32 });
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.nostr, this.#keyEpoch, (secretKey) => {
        const key = nip44ConversationKey(secretKey, peerKey);
        try {
          return nip44EncryptWithKey(key, plaintext);
        } finally {
          wipe(key);
        }
      }),
    );
  }

  async nip44Decrypt(peer: string, payload: string, options?: EpochOptions): Promise<string> {
    const epoch = this.#epochOf(options);
    const peerKey = decodeHex(peer, { length: 32 });
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.nostr, epoch, (secretKey) => {
        const key = nip44ConversationKey(secretKey, peerKey);
        try {
          return nip44DecryptWithKey(key, payload);
        } finally {
          wipe(key);
        }
      }),
    );
  }

  async unwrapCek(
    wrapped: WrappedCek,
    envelopeId: Uint8Array,
    options?: EpochOptions,
  ): Promise<Uint8Array> {
    const epoch = this.#epochOf(options);
    if (typeof wrapped !== 'object' || wrapped === null) {
      throw new CryptoInputError('invalid_argument', 'unwrapCek: wrapped must be {enc, wk}');
    }
    const { enc, wk } = wrapped as unknown as Record<string, unknown>;
    const entry = { enc: bytesCopy(enc, 'unwrapCek: enc'), wk: bytesCopy(wk, 'unwrapCek: wk') };
    const id = bytesCopy(envelopeId, 'unwrapCek: envelopeId');
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.enc, epoch, (secretKey) => unwrapCek(secretKey, entry, id)),
    );
  }

  async sign712(typedData: TypedData): Promise<string> {
    // The EVM key exists only at epoch 0 (04 §2.1), whatever the current key epoch.
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.evm, 0, (secretKey) => signTypedData(typedData, secretKey)),
    );
  }

  async signTransaction(tx: DirectTransaction): Promise<string> {
    // 07 §6.2: checked against the direct-mode rules first, with this agent's own address as the
    // only withdraw recipient. The EVM key exists only at epoch 0 (04 §2.1).
    const snapshot = directTransactionSnapshot(tx, this.#agentId);
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.evm, 0, (secretKey) =>
        signDirectTransaction(secretKey, snapshot, this.#agentId),
      ),
    );
  }

  async signCardPop(card: AgentCard): Promise<string> {
    // 04 §2.9 (D-102): only the own card at the current epoch, checked before the seed is read.
    let parsed: AgentCard;
    try {
      parsed = parseAgentCard(card);
    } catch {
      throw notOwnCard();
    }
    if (parsed.agentEvm !== this.#agentId || parsed.keyEpoch !== this.#keyEpoch) {
      throw notOwnCard();
    }
    return this.#withSeed((seed) => {
      const own = cardPopSnapshot(parsed, derivePublicIdentity(seed, this.#keyEpoch));
      return withSecret(seed, KEY_LABELS.nostr, this.#keyEpoch, (secretKey) =>
        encodeHex(signCardPop(secretKey, own)),
      );
    });
  }

  async signDropRequest(
    request: DropAuthRequest,
    createdAt: number,
    options?: EpochOptions,
  ): Promise<string> {
    const snapshot = dropRequestSnapshot(request, createdAt);
    const epoch = dropRequestEpoch(snapshot, options, this.#keyEpoch);
    return this.#withSeed((seed) =>
      withSecret(seed, KEY_LABELS.drop, epoch, (secretKey) =>
        signDropRequest(secretKey, snapshot, createdAt),
      ),
    );
  }

  /**
   * The store key of the `enc` columns (CLOUD_STORE_KEY_INFO), for the store cipher. Derived for this
   * call only and wiped when `fn` settles; `fn` must not keep it.
   */
  async withStoreKey<T>(fn: (storeKey: Uint8Array) => T | Promise<T>): Promise<T> {
    return this.#withSeed(async (seed) => {
      const key = hkdfSha256(
        seed,
        encodeUtf8(STORE_KEY_SALT),
        encodeUtf8(CLOUD_STORE_KEY_INFO),
        32,
      );
      try {
        return await fn(key);
      } finally {
        wipe(key);
      }
    });
  }

  close(): Promise<void> {
    this.#closed = true;
    return Promise.resolve();
  }
}
